package com.repairconnect.controller;
import com.repairconnect.entity.*; import com.repairconnect.repository.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasRole('ADMIN')") public class AdminController {final UserRepository users;final ProviderRepository providers;final BookingRepository bookings;final CustomerRepository customers; AdminController(UserRepository u,ProviderRepository p,BookingRepository b,CustomerRepository c){users=u;providers=p;bookings=b;customers=c;} @GetMapping("/dashboard") Map<String,Object> dashboard(){return Map.of("customers",users.countByRole(Role.CUSTOMER),"providers",users.countByRole(Role.SERVICE_PROVIDER),"approvedProviders",providers.findByVerificationStatus(VerificationStatus.APPROVED).size(),"pendingProviders",providers.findByVerificationStatus(VerificationStatus.PENDING).size(),"bookings",bookings.count(),"completedBookings",bookings.countByStatus(BookingStatus.COMPLETED),"cancelledBookings",bookings.countByStatus(BookingStatus.CANCELLED));} @GetMapping("/providers") List<ProviderProfile> all(){return providers.findAll();} @PutMapping("/providers/{id}/{decision}") ProviderProfile decision(@PathVariable Long id,@PathVariable String decision){var p=providers.findById(id).orElseThrow();p.setVerificationStatus(decision.equals("approve")?VerificationStatus.APPROVED:VerificationStatus.REJECTED);return providers.save(p);} @GetMapping("/bookings") List<Booking> allBookings(){return bookings.findAll();} @GetMapping("/customers") List<CustomerProfile> allCustomers(){return customers.findAll();} }